function scr_teevie_screen(arg0) constructor
{
    static init = function()
    {
        set_screen();
    };

    static get_tile_pos = function()
    {
        return _tile_pos;
    };

    static set_screen_sprite = function(arg0)
    {
        _screensprite = arg0;
    };

    static get_screen_sprite = function()
    {
        return _screensprite;
    };

    static set_screen_image_index = function(arg0)
    {
        _screenimage = arg0;
    };

    static get_screen_image_index = function()
    {
        return _screenimage;
    };

    static is_animated = function()
    {
        return _screenanimate;
    };

    static disable_animation = function()
    {
        _screenanimate = false;
    };

    static set_screen_con = function(arg0)
    {
        _screencon = arg0;
    };

    static get_screen_con = function()
    {
        return _screencon;
    };

    static set_screen_color = function(arg0)
    {
        _screencolor = arg0;
    };

    static get_screen_color = function()
    {
        return _screencolor;
    };

    static increment_screen_timer = function()
    {
        _screentimer += 1;
    };

    static set_screen_timer = function(arg0)
    {
        _screentimer = arg0;
    };

    static get_screen_timer = function()
    {
        return _screentimer;
    };

    static set_screen_offset = function(arg0)
    {
        _screenimageoffset = arg0;
    };

    static get_screen_offset = function()
    {
        return _screenimageoffset;
    };

    static set_screen = function()
    {
        var random_image_index = choose(0, 2, 4, 8, 19, 23, 31, 35, 37, 39);
        set_screen_image_index(random_image_index);
        switch (random_image_index)
        {
            case 0:
                set_screen_color(c_aqua);
                break;
            case 2:
                set_screen_color(c_yellow);
                break;
            case 4:
                set_screen_color(#FFD4B3);
                set_screen_con(2);
                break;
            case 8:
                set_screen_color(c_aqua);
                set_screen_con(3);
                break;
            case 19:
                set_screen_color(#FFD4B3);
                set_screen_con(4);
                break;
            case 23:
                set_screen_color(#AFC170);
                set_screen_con(5);
                break;
            case 31:
                set_screen_color(#FF8A2D);
                set_screen_con(6);
                break;
            case 35:
                set_screen_color(#777A34);
                set_screen_con(7);
                break;
            case 37:
                set_screen_color(c_black);
                set_screen_con(8);
                break;
            case 39:
                set_screen_color(#6F95B7);
                set_screen_con(9);
                break;
            default:
                set_screen_color(c_aqua);
                break;
        }
    };

    static set_static = function()
    {
        set_screen_timer(0);
        set_screen_con(1);
        set_screen_sprite(spr_dw_teevie_tv_static);
        set_screen_image_index(0);
        set_screen_color(c_white);
        set_screen_offset(0);
    };

    _tile_pos = arg0;
    _screensprite = spr_dw_teevie_tv_shows;
    _screencon = 0;
    _screentimer = floor(random(100) - 100);
    _screencolor = c_white;
    _screenanimate = true;
    _screenimageoffset = 0;
    _screenimage = 0;
}

if (init == 0)
{
    for (var i = 0; i < width; i++)
    {
        var tile_x = i;
        for (var j = 0; j < height; j++)
        {
            var tile_y = j;
            var new_screen = new scr_teevie_screen(new Vector2(tile_x, tile_y));
            new_screen.init();
            _screen_list[array_length(_screen_list)] = new_screen;
        }
    }
    init = 1;
}
for (var i = 0; i < array_length(_screen_list); i++)
{
    var screen = _screen_list[i];
    var screencon = screen.get_screen_con();
    if (mode == 0)
    {
        if (screencon == 0)
        {
            if (screen.is_animated())
            {
                screen.increment_screen_timer();
            }
            if ((abs(screen.get_screen_timer()) % 8) == 0)
            {
                if (screen.get_screen_offset() == 0)
                {
                    screen.set_screen_offset(1);
                }
                else
                {
                    screen.set_screen_offset(0);
                }
            }
            if (abs(screen.get_screen_timer()) >= 120)
            {
                screen.set_static();
            }
        }
        else if (screencon == 1)
        {
            if (screen.is_animated())
            {
                screen.increment_screen_timer();
            }
            if ((abs(screen.get_screen_timer()) % 2) == 0)
            {
                if (screen.get_screen_offset() == 0)
                {
                    screen.set_screen_offset(1);
                }
                else
                {
                    screen.set_screen_offset(0);
                }
            }
            if (abs(screen.get_screen_timer()) >= 15)
            {
                var random_timer = -100 + floor(random(100));
                screen.set_screen_timer(random_timer);
                screen.set_screen_con(0);
                screen.set_screen_sprite(spr_dw_teevie_tv_shows);
                screen.set_screen();
            }
        }
        else if (screencon == 2)
        {
            if (screen.is_animated())
            {
                screen.increment_screen_timer();
            }
            if ((abs(screen.get_screen_timer()) % 4) == 0)
            {
                var offset = screen.get_screen_offset();
                screen.set_screen_offset(offset + 1);
                if (screen.get_screen_offset() == 4)
                {
                    screen.set_screen_offset(0);
                }
            }
            if (abs(screen.get_screen_timer()) >= 120)
            {
                screen.set_static();
            }
        }
        else if (screencon == 3)
        {
            if (screen.is_animated())
            {
                screen.increment_screen_timer();
            }
            if ((abs(screen.get_screen_timer()) % 4) == 0)
            {
                var offset = screen.get_screen_offset();
                screen.set_screen_offset(offset + 1);
                if (screen.get_screen_offset() == 11)
                {
                    screen.set_screen_offset(0);
                }
            }
            if (abs(screen.get_screen_timer()) >= 120)
            {
                screen.set_static();
            }
        }
        else if (screencon == 4)
        {
            if (screen.is_animated())
            {
                screen.increment_screen_timer();
            }
            if ((abs(screen.get_screen_timer()) % 4) == 0)
            {
                var offset = screen.get_screen_offset();
                screen.set_screen_offset(offset + 1);
                if (screen.get_screen_offset() == 4)
                {
                    screen.set_screen_offset(0);
                }
            }
            if (abs(screen.get_screen_timer()) >= 120)
            {
                screen.set_static();
            }
        }
        else if (screencon == 5)
        {
            if (screen.is_animated())
            {
                screen.increment_screen_timer();
            }
            if ((abs(screen.get_screen_timer()) % 4) == 0)
            {
                var offset = screen.get_screen_offset();
                if (offset < 7)
                {
                    screen.set_screen_offset(offset + 1);
                }
            }
            if (abs(screen.get_screen_timer()) >= 20)
            {
                screen.set_static();
            }
        }
        else if (screencon == 6)
        {
            if (screen.is_animated())
            {
                screen.increment_screen_timer();
            }
            if ((abs(screen.get_screen_timer()) % 4) == 0)
            {
                var offset = screen.get_screen_offset();
                screen.set_screen_offset(offset + 1);
                if (screen.get_screen_offset() == 4)
                {
                    screen.set_screen_offset(0);
                }
            }
            if (abs(screen.get_screen_timer()) >= 120)
            {
                screen.set_static();
            }
        }
        else if (screencon == 7)
        {
            if (screen.is_animated())
            {
                screen.increment_screen_timer();
            }
            if ((abs(screen.get_screen_timer()) % 6) == 0)
            {
                var offset = screen.get_screen_offset();
                screen.set_screen_offset(offset + 1);
                if (screen.get_screen_offset() == 2)
                {
                    screen.set_screen_offset(0);
                }
            }
            if (abs(screen.get_screen_timer()) >= 120)
            {
                screen.set_static();
            }
        }
        else if (screencon == 8)
        {
            if (screen.is_animated())
            {
                screen.increment_screen_timer();
            }
            if ((abs(screen.get_screen_timer()) % 6) == 0)
            {
                var offset = screen.get_screen_offset();
                screen.set_screen_offset(offset + 1);
                if (screen.get_screen_offset() == 2)
                {
                    screen.set_screen_offset(0);
                }
            }
            if (abs(screen.get_screen_timer()) >= 120)
            {
                screen.set_static();
            }
        }
        else if (screencon == 9)
        {
            if (screen.is_animated())
            {
                screen.increment_screen_timer();
            }
            if ((abs(screen.get_screen_timer()) % 6) == 0)
            {
                var offset = screen.get_screen_offset();
                screen.set_screen_offset(offset + 1);
                if (screen.get_screen_offset() == 2)
                {
                    screen.set_screen_offset(0);
                }
            }
            if (abs(screen.get_screen_timer()) >= 120)
            {
                screen.set_static();
            }
        }
    }
}

